/* 第一章《三角形》材料整理：基础知识。 */
TID("c1-01","1.1","三角形概念、基本要素与按角分类","三角形由不在同一直线上的三条线段首尾顺次相接组成；有三个顶点、三条边、三个内角。按角可分为锐角、直角、钝角三角形。","判断是否为三角形先检查三条线段是否首尾顺次相接并形成封闭图形；数三角形时按给定边或顶点逐个枚举。","三条线段相交不一定构成三角形；按角分类只看最大角即可。",
 Q("选择题","下列由三根木棒拼成的图形描述中，符合三角形概念的是（　）。","D",["三角形必须由三条线段首尾顺次相接，并组成封闭图形。","D 满足上述条件。"],["三条线段中有两个端点没有相接","三条线段相交，但不是首尾顺次相接","三条线段首尾相接但未形成封闭图形","三条线段首尾顺次相接并形成封闭图形"]),
 Q("选择题","在一个图形中，A、D、E 三个点分别与 B、C 相连，并分别与边 BC 组成三角形。以 BC 为边的三角形共有（　）。","C",["以 BC 为公共边，第三个顶点可以是 A、D、E。","因此共有 3 个三角形。"],["1个","2个","3个","4个"]),
 Q("填空题","在 △ABC 中，D 在线段 BC 上，连接 AD。图中共有____个三角形；以 AD 为边的三角形有____。","3；△ABD、△ADC",["图中可数出 △ABC、△ABD、△ADC，共 3 个。","以 AD 为边的只有 △ABD、△ADC。"],[]),
 Q("选择题","三角形按角分类可以分为（　）。","A",["按角分类时，根据最大角是锐角、直角还是钝角，可分为锐角三角形、直角三角形、钝角三角形。"],["锐角三角形、直角三角形、钝角三角形","等腰三角形、等边三角形、不等边三角形","直角三角形、等腰直角三角形","以上答案都不正确"]));

TID("t02","1.1","内角和、直角三角形与分类","三角形内角和为 180°；直角三角形两个锐角互余。有两个角互余，或有一个内角为 90°，可判定为直角三角形。","角度题优先利用内角和、平行线角关系和直角三角形两锐角互余；按角分类时看最大角。","两内角互余作为性质使用时要注意所在三角形；平行线产生的对应角、内错角关系要先写依据。",
 Q("选择题","△ABC 中，D 在 BC 上，过 A 作 AD；过 B 作 BE，且 AD∥BE。若 ∠CAD=25°，∠EBC=80°，则 ∠ACB 的度数为（　）。","B",["由 AD∥BE，得 ∠ADC=∠EBC=80°。","在 △ACD 中，∠ACB=180°−25°−80°=75°。"],["65°","75°","85°","95°"]),
 Q("填空题","一个三角形的三个内角度数之比为 1∶2∶7，则最小内角的度数是____。","18°",["设最小角为 x°，则 x+2x+7x=180°。","10x=180°，得 x=18°。"],[]),
 Q("选择题","若 △ABC 的三个内角度数之比为 3∶5∶2，则 △ABC 是（　）。","C",["设三个角分别为 3x、5x、2x，则 10x=180°，x=18°。","最大角 5x=90°，所以是直角三角形。"],["不能确定三角形的形状","锐角三角形","直角三角形","钝角三角形"]),
 Q("选择题","在 Rt△ABC 中，∠C=90°，D 在 CB 上，E 在 AB 上，且 ∠BDE=∠A，则 △BDE 为（　）。","B",["在 Rt△ABC 中，∠A+∠B=90°。","∠BDE=∠A，所以 ∠BDE+∠B=90°，从而 ∠DEB=90°。","因此 △BDE 为直角三角形。"],["锐角三角形","直角三角形","钝角三角形","以上均有可能"]));

TID("c1-02","1.1","按边分类与等腰三角形","按边可分为不等边三角形和等腰三角形；等边三角形是三边相等的特殊等腰三角形。一个三角形可同时属于按边和按角的不同类别。","先判断边的相等关系，再用内角和或最大角判断按角分类；集合图中注意等边三角形包含于等腰三角形。","“等腰”与“锐角/直角/钝角”属于不同分类标准，不能混为一类。",
 Q("选择题","等边三角形是（　）。","B",["等边三角形三个内角都为 60°。","三个角均为锐角，所以是锐角三角形。"],["直角三角形","锐角三角形","钝角三角形","等腰直角三角形"]),
 Q("选择题","用集合表示按边分类时，大集合表示等腰三角形，小椭圆 A 完全包含在其中；不等边三角形在另一部分。A 表示（　）。","D",["等边三角形三边相等，是等腰三角形的特殊情形。","因此小椭圆 A 表示等边三角形。"],["直角三角形","锐角三角形","钝角三角形","等边三角形"]),
 Q("选择题","四个三角形各有一部分被遮挡：A 可看见两个角，B 可看见一个直角，C 只看见一个锐角，D 可看见一个钝角。其中不能判断三角形类型的是（　）。","C",["A 可由两个角求第三角；B 已知有直角；D 已知有钝角，均可判断。","C 只知道一个锐角，另外两个角未知，不能判断。"],["A","B","C","D"]),
 Q("填空题","若三角形三边之比为 2∶3∶3，周长为 32 cm，则三边长分别为____；按边分是____三角形。","8 cm、12 cm、12 cm；等腰",["设三边为 2x、3x、3x，则 2x+3x+3x=32。","解得 x=4，三边为 8、12、12。","有两边相等，所以是等腰三角形。"],[]));

TID("t01","1.1","三边关系与第三边范围","三角形任意两边之和大于第三边、任意两边之差小于第三边；已知两边 a>b 时，第三边 c 满足 a−b<c<a+b。","涉及等腰三角形时要分类讨论某条已知边是腰还是底边，并在最后用三边关系检验；已知两边求第三边时先写严格范围。","三边关系的两个端点不能取等号；分类讨论得到的候选结果必须再次检验能否组成三角形。",
 Q("选择题","等腰三角形的一边长为 6，另一边长为 13，则它的周长为（　）。","C",["若腰长为 6，则 6+6=12<13，不能组成三角形。","若腰长为 13，则三边为 13、13、6，可组成三角形，周长为 32。"],["25","25或32","32","19"]),
 Q("选择题","小芳有两根长度为 6 cm 和 9 cm 的木条，要再选一根组成三角形。下列可选的是（　）。","C",["设第三边为 x，则 9−6<x<9+6，即 3<x<15。","四个选项中只有 12 cm 满足。"],["2 cm","3 cm","12 cm","15 cm"]),
 Q("选择题","等腰三角形周长为 21 cm，如果其中一边长为 5 cm，那么另两边长为（　）。","B",["若 5 为腰，底边为 11，但 5+5<11，不能组成三角形。","若 5 为底边，两腰均为 (21−5)÷2=8，可组成三角形。"],["5，8","8，8","5，11","11，11"]),
 Q("填空题","已知三角形三边长分别为 3、x、9，则 |x−5|+|x−13|=____。","8",["由三边关系得 6<x<12。","因此 x−5>0，x−13<0。","原式=(x−5)+(13−x)=8。"],[]));

TID("c1-03","1.1","三边关系综合与代数化简","三边关系既可判断三角形是否存在，也可确定字母取值范围，并据此判断绝对值内式子的正负。","判断是否构成三角形时只需比较最小两边之和与最大边；含字母时先由三边关系确定范围，再做代数化简或筛选方程解。","不能只解方程而忽略三角形存在条件；非负数之和为 0 时，每一项都应为 0。",
 Q("解答题","已知三角形两边长为 a、b，且 a>b，写出第三边 c 的取值范围。","a−b<c<a+b",["由任意两边之差小于第三边，得 a−b<c。","由任意两边之和大于第三边，得 c<a+b。","合并得 a−b<c<a+b。"],[]),
 Q("选择题","下列四组三条线段中，能组成三角形的是（　）。","A",["比较最小两边之和与最大边。","3+4>5，可以组成；2+2=4、1+4=5、2+3<6 均不能组成。"],["3，4，5","2，2，4","1，4，5","2，3，6"]),
 Q("填空题","已知 a、b、c 为三角形的三边，则 a+b+c____2a（填“>”“=”或“<”）。",">",["由三边关系 b+c>a。","两边同时加 a，得 a+b+c>2a。"],[]),
 Q("填空题","已知 a、b、c 是 △ABC 的三边长，(b−2)²+|c−3|=0，且 a 为方程 |x−4|=2 的解，则 △ABC 的周长为____。","7",["由非负数之和为 0，得 b=2、c=3。","|x−4|=2 的解为 a=2 或 6。","三边关系要求 1<a<5，所以 a=2。","周长为 2+2+3=7。"],[]));

TID("t03","1.1","中线、高与面积分割","中线连接顶点与对边中点，并把三角形分成面积相等的两部分；高是顶点到对边所在直线的垂线段。三条高所在直线交于垂心。","中线题先写出对边两段相等；涉及周长时把公共线段抵消；高线判断要同时满足“从顶点出发”和“垂直于对边所在直线”。","中线不一定是高；钝角三角形的高可能在三角形外；垂心位置随三角形类型改变。",
 Q("选择题","在 △ABC 中，D、E、F 在 BC 上。已知 AF 连接顶点 A 与 BC 的中点 F，则下列线段中是 △ABC 中线的是（　）。","C",["三角形中线连接一个顶点与其对边中点。","F 是 BC 中点，所以 AF 是中线。"],["AD","AE","AF","MN"]),
 Q("选择题","AE 是 △ABC 的中线，E 在 BC 上。已知 EC=4，D 在线段 BE 上且 DE=2，则 BD 的长为（　）。","A",["AE 是中线，所以 BE=EC=4。","BD=BE−DE=4−2=2。"],["2","3","4","6"]),
 Q("填空题","△ABC 周长为 21 cm，AB=6 cm，BC 边上的中线 AD=5 cm，△ABD 周长为 15 cm，则 AC=____cm。","7",["由 AB+AD+BD=15，得 BD=4。","D 为 BC 中点，所以 BC=2BD=8。","由 AB+AC+BC=21，得 AC=7。"],[]),
 Q("选择题","BD 是 △ABC 的高，EF∥AC，EF 与 BD 交于 G。判断：①BG 是 △EBF 的高；②CD 是 △BGC 的高；③DG 是 △AGC 的高；④AD 是 △ABG 的高。正确的有（　）。","D",["BD⊥AC 所在直线，且 EF∥AC，所以 BD⊥EF。","由这些垂直关系可逐项判断 ①②③④ 都满足相应三角形高的定义。"],["1个","2个","3个","4个"]));

TID("c1-04","1.1","角平分线、高与垂心","三角形角平分线是从顶点到对边的线段；三条角平分线交于内心。三条高所在直线交于垂心：锐角三角形垂心在内部，直角三角形在直角顶点，钝角三角形在外部。","角平分线题用“两个角相等”表达；作高时三角尺一条直角边与底边重合，另一条直角边必须经过对应顶点。","单独一个角的平分线是射线，而三角形的角平分线是线段；垂心是高所在直线的交点。",
 Q("选择题","从 A 向 BC 引出 AD、AE、AF。已知 ∠DAE=∠EAF，且 ∠BAD=∠FAC。下列结论：①AD 平分 ∠BAF；②AF 平分 ∠BAC；③AE 平分 ∠DAF；④AF 平分 ∠DAC；⑤AE 平分 ∠BAC。正确的有（　）。","C",["由 ∠DAE=∠EAF，AE 平分 ∠DAF，所以③正确。","又由 ∠BAD=∠FAC，可得 ∠BAE=∠EAC，所以 AE 平分 ∠BAC，⑤正确。","其余结论不能由已知推出，共 2 个正确。"],["4个","3个","2个","1个"]),
 Q("选择题","直角三角形的两锐角平分线相交形成的两个角，其度数是（　）。","C",["直角三角形两个锐角之和为 90°。","两条角平分线分别取一半，结合三角形内角和，可得交点处一对邻补角为 135° 和 45°。"],["45°","135°","45°或135°","以上答案均不对"]),
 Q("选择题","用三角尺作 △ABC 的边 BC 上的高，正确的摆放方法是（　）。","B",["作 BC 边上的高，应使三角尺一条直角边与 BC 重合。","另一条直角边必须经过顶点 A。","符合这两个条件的是 B。"],["直角边过B但不过A","一条直角边与BC重合，另一条经过A","斜边与BC重合","直角顶点放在A且两直角边都不与BC重合"]),
 Q("选择题","如果一个三角形的三条高所在直线的交点恰好是三角形的一个顶点，那么这个三角形是（　）。","C",["锐角三角形的垂心在内部，钝角三角形的垂心在外部。","直角三角形两条直角边本身就是两条高，垂心在直角顶点。"],["锐角三角形","钝角三角形","直角三角形","等边三角形"]));
